513	const MONTHS = ["Jan","Feb","Mar","Apr","May","Jun","Jul","Aug","Sep","Oct","Nov","Dec"];
514	// Format from the string parts. Parsing "2026-08-16" as a Date would drag the
515	// value through UTC and can land the label on the previous day.
516	const dLabel = s => `${+s.slice(8, 10)} ${MONTHS[+s.slice(5, 7) - 1]}`;
517	const dLong  = s => `${dLabel(s)} ${s.slice(0, 4)}`;
518	const dMonth = s => `${MONTHS[+s.slice(5, 7) - 1]} ${s.slice(0, 4)}`;
519	
520	const num = (v, dp = 0) => v == null ? "—"
521	  // collapse -0 and float dust to a clean zero: an axis reading "-0" is noise
522	  : (Math.abs(v) < 5e-10 ? 0 : v).toLocaleString("en-GB",
523	      { minimumFractionDigits: dp, maximumFractionDigits: dp });
524	/** kEUR -> a compact signed money string. */
525	const money = (k, dp = 1) => {
526	  if (k == null) return "—";
527	  const s = k < 0 ? "−" : "+", a = Math.abs(k);
528	  if (a >= 1000) return `${s}€${num(a / 1000, dp)}M`;
529	  return `${s}€${num(a, 0)}k`;
530	};
