532	/* ========================================================================== *
533	 * tiny svg helpers
534	 * ========================================================================== */
535	
536	const SVGNS = "http://www.w3.org/2000/svg";
537	function el(name, attrs = {}, text) {
538	  const n = document.createElementNS(SVGNS, name);
539	  for (const k in attrs) if (attrs[k] != null) n.setAttribute(k, attrs[k]);
540	  if (text != null) n.textContent = text;
541	  return n;
542	}
543	const scale = (d0, d1, r0, r1) => v => r0 + (v - d0) / ((d1 - d0) || 1) * (r1 - r0);
544	
545	/** Bar path with the data-end rounded and the baseline end square. */
546	function barPath(x, y, w, h, r, roundUp) {
547	  r = Math.max(0, Math.min(r, w / 2, h));
548	  if (h <= 0.6) return `M${x} ${y}h${w}`;               // hairline for ~zero
549	  return roundUp
550	    ? `M${x} ${y + h}V${y + r}q0 ${-r} ${r} ${-r}h${w - 2 * r}q${r} 0 ${r} ${r}V${y + h}Z`
551	    : `M${x} ${y}V${y + h - r}q0 ${r} ${r} ${r}h${w - 2 * r}q${r} 0 ${r} ${-r}V${y}Z`;
552	}
553	
554	/** Which x positions get a date label.
555	 *  Counted back from the last day, so the most recent date is always labelled
556	 *  and the spacing stays even -- labelling every nth from the left and then
557	 *  forcing the last one lands two labels on top of each other. How many fit is
558	 *  a function of the plot width, not a constant: eight labels that breathe on a
559	 *  desktop run into each other at 390px. */
560	function labelIndices(n, plotW) {
561	  const target = Math.max(3, Math.min(8, Math.floor(plotW / 72)));
562	  const every = Math.max(1, Math.ceil(n / target));
563	  const idx = new Set();
564	  for (let i = n - 1; i >= 0; i -= every) idx.add(i);
565	  return idx;
566	}
567	
568	/** Nice round tick values covering [lo, hi], aiming for ~count steps. */
569	function ticks(lo, hi, count = 5) {
570	  const span = (hi - lo) || 1;
571	  const raw = span / count;
572	  const mag = Math.pow(10, Math.floor(Math.log10(raw)));
573	  const step = [1, 2, 2.5, 5, 10].map(m => m * mag).find(s => s >= raw) || 10 * mag;
574	  const out = [];
575	  for (let t = Math.ceil(lo / step) * step; t <= hi + step * 1e-6; t += step) out.push(t);
576	  return out;
577	}
