583	const tip = document.getElementById("tip");
584	function showTip(evt, html) {
585	  tip.innerHTML = html;
586	  tip.style.opacity = 1;
587	  const pad = 12, w = tip.offsetWidth;
588	  let x = evt.clientX;
589	  x = Math.max(w / 2 + 4, Math.min(x, window.innerWidth - w / 2 - 4));
590	  tip.style.left = x + "px";
591	  tip.style.top = Math.max(tip.offsetHeight + 4, evt.clientY - pad) + "px";
592	}
593	const hideTip = () => { tip.style.opacity = 0; };
594	/** The day tooltip, shared by the balance, price, volume and residual charts.
595	 *
596	 *  Leads with the transit-free basis because that is what the price chart plots --
597	 *  it used to print the gross basis instead, so the tooltip and the line under the
598	 *  cursor disagreed by up to 136 EUR/MWh. Both are shown: the gross pair is the
599	 *  honest denominator and the stripped pair is a bound, so neither stands alone.
600	 */
601	/** The two price rows, on whichever basis the day actually has.
602	 *
603	 *  A day can carry the gross pair without the transit-free pair. Falling back with `??`
604	 *  would print the gross number under the stripped label -- so name the basis instead of
605	 *  substituting quietly, and only offer the second row when there are two to compare.
606	 */
607	function pxRows(d) {
608	  const own = d.imp_px_own != null || d.exp_px_own != null;
609	  const row = (label, v) =>
610	    `<div class="t-row"><span>${label}</span><span>${v == null ? "—" : num(v, 1)}</span></div>`;
611	  if (!own)
612	    return row("Price when importing", d.imp_px_de) + row("Price when exporting", d.exp_px_de);
613	  return row("Price when importing", d.imp_px_own)
614	       + row("Price when exporting", d.exp_px_own)
615	       + `<div class="t-row"><span>&nbsp;&nbsp;same, counting transit</span>`
616	       + `<span>${num(d.imp_px_de, 1)} / ${num(d.exp_px_de, 1)}</span></div>`;
617	}
618	
619	function tipRows(d) {
620	  return `<div class="t-date">${dLong(d.date)}</div>
621	    <div class="t-row"><span>Balance</span><span>${money(d.bal_de_keur, 2)}</span></div>
622	    <div class="t-sep"></div>
623	    <div class="t-row"><span>Imported</span><span>${num(d.import_gwh, 1)} GWh</span></div>
624	    <div class="t-row"><span>Exported</span><span>${num(d.export_gwh, 1)} GWh</span></div>
625	    <div class="t-row"><span>of which in transit</span><span>${num(d.transit_gwh, 1)} GWh</span></div>
626	    ${pxRows(d)}
627	    <div class="t-row"><span>Congestion rent</span><span>${money(d.rent_keur, 2)}</span></div>`;
628	}
