630	/* ========================================================================== *
631	 * charts
632	 * ========================================================================== */
633	
634	const PLOT_H = 210, PAD = { t: 12, r: 16, b: 26, l: 52 };
635	const BAR_MAX = 24, GAP = 2, RAD = 4;
636	
637	/** Bar width for a band, for `per` bars sharing it.
638	 *  Clamped above zero: a year of days on a phone gives a band under 2px, and
639	 *  band - GAP then goes negative, which SVG rejects outright. */
640	const barW = (band, per = 1) =>
641	  Math.max(0.5, Math.min(BAR_MAX, (band - GAP * per) / per));
642	
643	/** Columns growing from a zero line, red below / blue above. */
644	function drawBalance(host, days) {
645	  const W = host.clientWidth || 720, H = PLOT_H + PAD.t + PAD.b;
646	  const svg = el("svg", { viewBox: `0 0 ${W} ${H}`, width: W, height: H,
647	                          role: "img", "aria-label": "Daily balance, million euro" });
648	  const x0 = PAD.l, x1 = W - PAD.r, y0 = PAD.t, y1 = PAD.t + PLOT_H;
649	
650	  const vals = days.map(d => d.bal_de_keur ?? 0);
651	  const lo = Math.min(0, ...vals), hi = Math.max(0, ...vals);
652	  // a lane past the extreme, so its label sits below the deepest bar instead of
653	  // landing in the date row
654	  const y = scale(lo - (hi - lo) * .10, hi, y1, y0);
655	
656	  for (const t of ticks(lo, hi)) {                          // hairline, solid
657	    svg.append(el("line", { class: t === 0 ? "axisline" : "gridline",
658	                            x1: x0, x2: x1, y1: y(t), y2: y(t) }));
659	    svg.append(el("text", { class: "tick", x: x0 - 8, y: y(t) + 4, "text-anchor": "end" },
660	                  (t < 0 ? "−" : "") + num(Math.abs(t) / 1000, 1) + "M"));
661	  }
662	
663	  const band = (x1 - x0) / days.length;
664	  const bw = barW(band);
665	  const worst = days.reduce((a, b) => (b.bal_de_keur ?? 0) < (a.bal_de_keur ?? 0) ? b : a, days[0]);
666	  const labels = labelIndices(days.length, x1 - x0);
667	
668	  days.forEach((d, i) => {
669	    const v = d.bal_de_keur ?? 0, up = v >= 0;
670	    const cx = x0 + band * (i + .5), top = Math.min(y(v), y(0));
671	    svg.append(el("path", {
672	      d: barPath(cx - bw / 2, top, bw, Math.abs(y(v) - y(0)), RAD, up),
673	      fill: up ? "var(--in)" : "var(--out)",
674	    }));
675	    // hit target spans the whole band, so it clears the 24px minimum
676	    const hit = el("rect", { class: "hit", x: cx - band / 2, y: y0, width: band, height: PLOT_H });
677	    hit.addEventListener("pointerenter", e => showTip(e, tipRows(d)));
678	    hit.addEventListener("pointermove", e => showTip(e, tipRows(d)));
679	    hit.addEventListener("pointerleave", hideTip);
680	    svg.append(hit);
681	
682	    if (d === worst) {                     // label the extreme only, never every bar
683	      svg.append(el("text", { class: "val", x: cx, y: y(v) + (v < 0 ? 14 : -7),
684	                              "text-anchor": "middle" }, money(v)));
685	    }
686	    if (labels.has(i)) {
687	      svg.append(el("text", { x: cx, y: y1 + 17, "text-anchor": "middle" }, dLabel(d.date)));
688	    }
689	  });
690	
691	  host.replaceChildren(svg);
692	}
