694	/** Two price lines on one axis, with the gap between them washed in. */
695	function drawPrice(host, days) {
696	  // A band above the plot for the unit label. Without it the topmost tick and
697	  // the unit share a line whenever the data reaches the top of the scale, which
698	  // is exactly what a source with different price levels will do to you.
699	  const TOP = PAD.t + 14;
700	  const W = host.clientWidth || 720, H = PLOT_H + TOP + PAD.b;
701	  const R = PAD.r + 34;                                  // room for end labels
702	  const svg = el("svg", { viewBox: `0 0 ${W} ${H}`, width: W, height: H,
703	                          role: "img", "aria-label": "Volume-weighted price when importing and when exporting, euro per megawatt hour" });
704	  const x0 = PAD.l, x1 = W - R, y0 = TOP, y1 = TOP + PLOT_H;
705	
706	  // Prefer the transit-free basis: transit is bought and sold in the same hour at the
707	  // same price, so including it pulls both curves together. But it is a bound, not a
708	  // measurement -- see the hint under this chart.
709	  const ownBasis = days.some(d => d.imp_px_own != null);
710	  const fI = ownBasis ? "imp_px_own" : "imp_px_de", fE = ownBasis ? "exp_px_own" : "exp_px_de";
711	  const all = days.flatMap(d => [d[fI], d[fE]]).filter(v => v != null);
712	  const lo = Math.min(...all), hi = Math.max(...all);
713	  const pad = (hi - lo) * .12 || 1;
714	  const y = scale(lo - pad, hi + pad, y1, y0);
715	  // Band centres, not edge-to-edge: each value is a daily *average*, so it belongs
716	  // in the middle of its day rather than on a boundary -- and it puts these points
717	  // exactly above the columns in the panel below, which is the whole point of
718	  // pairing them.
719	  const band = (x1 - x0) / days.length;
720	  const x = i => x0 + band * (i + .5);
721	
722	  for (const t of ticks(lo - pad, hi + pad)) {
723	    svg.append(el("line", { class: "gridline", x1: x0, x2: x1, y1: y(t), y2: y(t) }));
724	    svg.append(el("text", { class: "tick", x: x0 - 8, y: y(t) + 4, "text-anchor": "end" }, num(t)));
725	  }
726	
727	  // The wash between the curves: the day's spread, ~10% opacity, never a block.
728	  // One polygon per unbroken run of days where BOTH prices exist. Filtering the two
729	  // edges independently -- which this did -- bridges each one's gaps separately, so
730	  // the fill asserted a spread across the 34 days where one leg was never measured,
731	  // and closed with a diagonal wedge wherever the two edges started on different days.
732	  let run = [];
733	  const flushBand = () => {
734	    if (run.length > 1) {
735	      const d = run.map(q => `${q[0]} ${y(q[1])}`).join("L") + "L"
736	              + [...run].reverse().map(q => `${q[0]} ${y(q[2])}`).join("L");
737	      svg.append(el("path", { d: `M${d}Z`, fill: "var(--out)", opacity: .10 }));
738	    }
739	    run = [];
740	  };
741	  days.forEach((d, i) => {
742	    if (d[fI] == null || d[fE] == null) { flushBand(); return; }
743	    run.push([x(i), d[fI], d[fE]]);
744	  });
745	  flushBand();
746	
747	  // segmented so a null day breaks the line rather than inventing a value
748	  for (const [field, colour] of [[fI, "var(--out)"], [fE, "var(--in)"]]) {
749	    let seg = [];
750	    const flush = () => {
751	      if (seg.length > 1) svg.append(el("path", {
752	        d: "M" + seg.map(p => `${p[0]} ${p[1]}`).join("L"),
753	        fill: "none", stroke: colour, "stroke-width": 2,
754	        "stroke-linejoin": "round", "stroke-linecap": "round",
755	      }));
756	      else if (seg.length === 1) svg.append(el("circle", {
757	        cx: seg[0][0], cy: seg[0][1], r: 2, fill: colour }));
758	      seg = [];
759	    };
760	    days.forEach((d, i) => d[field] == null ? flush() : seg.push([x(i), y(d[field])]));
761	    flush();
762	
763	    const last = days.filter(d => d[field] != null).pop();
764	    if (last) {
765	      const i = days.indexOf(last);
766	      svg.append(el("circle", { cx: x(i), cy: y(last[field]), r: 4, fill: colour,
767	                                stroke: "var(--surface)", "stroke-width": 2 }));
768	      svg.append(el("text", { class: "val", x: x(i) + 9, y: y(last[field]) + 4 },
769	                    num(last[field])));
770	    }
771	  }
772	  svg.append(el("text", { x: x0 - 8, y: y0 - 9, "text-anchor": "end" }, "€/MWh"));
773	
774	  // crosshair + nearest-point tooltip across the whole plot
775	  const cross = el("line", { class: "crosshair", y1: y0, y2: y1, x1: 0, x2: 0, opacity: 0 });
776	  svg.append(cross);
777	  const hit = el("rect", { class: "hit", x: x0, y: y0, width: x1 - x0, height: PLOT_H });
778	  const at = evt => {
779	    const box = svg.getBoundingClientRect();
780	    const px = (evt.clientX - box.left) * (W / box.width);
781	    const i = Math.max(0, Math.min(days.length - 1, Math.floor((px - x0) / band)));
782	    cross.setAttribute("x1", x(i)); cross.setAttribute("x2", x(i));
783	    cross.setAttribute("opacity", 1);
784	    showTip(evt, tipRows(days[i]));
785	  };
786	  hit.addEventListener("pointerenter", at);
787	  hit.addEventListener("pointermove", at);
788	  hit.addEventListener("pointerleave", () => { cross.setAttribute("opacity", 0); hideTip(); });
789	  svg.append(hit);
790	
791	  const labels = labelIndices(days.length, x1 - x0);
792	  days.forEach((d, i) => {
793	    if (labels.has(i))
794	      svg.append(el("text", { x: x(i), y: y1 + 17, "text-anchor": "middle" }, dLabel(d.date)));
795	  });
796	
797	  host.replaceChildren(svg);
798	}
