800	/** Imports above the axis, exports below: direction encoded twice. */
801	function drawVolume(host, days) {
802	  const H2 = 96, W = host.clientWidth || 720, H = H2 * 2 + PAD.t + PAD.b;
803	  const svg = el("svg", { viewBox: `0 0 ${W} ${H}`, width: W, height: H,
804	                          role: "img", "aria-label": "Imported and exported energy per day, gigawatt hours" });
805	  const x0 = PAD.l, x1 = W - PAD.r, mid = PAD.t + H2;
806	
807	  const top = Math.max(...days.map(d => Math.max(d.import_gwh ?? 0, d.export_gwh ?? 0)), 1);
808	  const h = v => (v ?? 0) / top * (H2 - 6);
809	
810	  for (const t of ticks(0, top, 3)) {
811	    if (t === 0) continue;
812	    for (const s of [-1, 1]) {
813	      svg.append(el("line", { class: "gridline", x1: x0, x2: x1,
814	                              y1: mid - s * h(t), y2: mid - s * h(t) }));
815	      svg.append(el("text", { class: "tick", x: x0 - 8, y: mid - s * h(t) + 4,
816	                              "text-anchor": "end" }, num(t)));
817	    }
818	  }
819	  svg.append(el("line", { class: "axisline", x1: x0, x2: x1, y1: mid, y2: mid }));
820	  svg.append(el("text", { x: x0 - 8, y: PAD.t - 2, "text-anchor": "end" }, "GWh"));
821	
822	  const band = (x1 - x0) / days.length;
823	  const bw = barW(band);
824	  const labels = labelIndices(days.length, x1 - x0);
825	  days.forEach((d, i) => {
826	    const cx = x0 + band * (i + .5);
827	    // Each side splits in two. Germany's own share -- power used here, or generated
828	    // here -- sits against the axis so it can be compared across days on a common
829	    // baseline; the transit overlap extends beyond it. The transit block is the
830	    // same height above and below by construction, which is the point: one flow
831	    // crossing the country, counted once in each direction.
832	    const thru = Math.min(d.transit_gwh ?? 0, d.import_gwh ?? 0, d.export_gwh ?? 0);
833	    const stack = (total, up, mine) => {
834	      const own = Math.max(0, total - thru);
835	      const dir = up ? -1 : 1;
836	      // inner segment: square both ends, it meets the axis and the next segment
837	      if (own > 0) {
838	        const hp = h(own);
839	        svg.append(el("rect", { x: cx - bw / 2, y: up ? mid - hp : mid,
840	                                width: bw, height: hp, fill: mine }));
841	      }
842	      // outer segment: rounded on the data end only, held off by the surface gap
843	      if (thru > 0) {
844	        const base = mid + dir * (h(own) + GAP);
845	        const hp = Math.max(0, h(thru) - GAP);
846	        svg.append(el("path", { d: barPath(cx - bw / 2, up ? base - hp : base,
847	                                           bw, hp, RAD, up), fill: "var(--thru)" }));
848	      }
849	    };
