1321	  const vE = useOwn ? "from_de_plants_gwh" : "export_gwh", pE = useOwn ? "exp_px_own" : "exp_px_de";
1322	  const impVol = days.reduce((a, d) => a + (d[vI] ?? 0), 0);
1323	  const expVol = days.reduce((a, d) => a + (d[vE] ?? 0), 0);
1324	  const impCost = days.reduce((a, d) => a + (d[vI] ?? 0) * (d[pI] ?? 0), 0);
1325	  const expRev  = days.reduce((a, d) => a + (d[vE] ?? 0) * (d[pE] ?? 0), 0);
