1388	/** Which month files a range of N days needs, newest first.
1389	 *  Derived from the manifest, so no data has to be downloaded to work it out. */
1390	function monthsFor(n) {
1391	  const all = state.index.months.map(m => m.month);
1392	  if (!n) return all;
1393	  const last = new Date(state.index.last_date + "T12:00:00Z");
1394	  const from = new Date(last.getTime() - (n - 1) * 864e5);
1395	  const cut = from.toISOString().slice(0, 7);
1396	  const need = all.filter(m => m >= cut);
1397	  // a range can start mid-month, so keep the month before the cut as well when the
1398	  // window opens before that month's first day
1399	  const i = all.indexOf(need[0]);
1400	  if (i > 0 && from.toISOString().slice(0, 10) < state.index.months[i].first) need.unshift(all[i - 1]);
1401	  return need;
1402	}
